pub(super) static ROWS_0: &[RawRow] = &[
    // bot/knowledge/kitchen_prep.py:42
    RawRow { id: "meat-room-temperature", domain: "kitchen_prep", reply: "It barely matters: twenty minutes on the counter warms the meat by a couple of degrees inside, so the middle still cooks the same. Leaving raw meat out for hours is a food safety risk. What does make a difference is patting it dry and seasoning it just before it goes in the pan - a dry surface browns, a wet one steams.", key: &[&["steak", "steaks", "chicken", "chicken breast", "turkey", "pork", "lamb", "beef", "fish", "meat", "the meat", "chops", "sausages"],&["room temperature", "out of the fridge", "rest out", "twenty minutes", "an hour before", "come to room", "warm up before", "before cooking", "before it goes in"],], grouped: true, avoid: &["keep", "keeps", "keeping", "how long", "left out", "overnight", "gone off", "still good", "defrost", "thaw", "freeze", "frozen", "wash", "washing", "rinse", "safe", "food poisoning", "pink", "raw in the middle", "is it cooked", "cooked through", "cooked to", "done", "how do i know", "what temperature", "how hot", "oven", "rest a joint", "resting", "prick", "pricking", "pricked", "pierce", "pierced", "split", "splits", "burst", "bursts", "skin", "skins"], ask: &[], slips: &[], bias: 1, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Pass, callback: Callback::Fixed, shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/kitchen_prep.py:426
    RawRow { id: "prep-sift", domain: "kitchen_prep", reply: "", key: &[&["sift", "sifts", "sifting", "sifted", "sieved", "sieve the"],&["need", "needs", "needed", "have to", "has to", "should", "must", "necessary", "worth", "point", "bother", "bothering", "essential", "important"],], grouped: true, avoid: &[], ask: &[], slips: &[], bias: 1, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Prep(super::kitchen_prep::Gate::Needed), callback: Callback::Prep(super::kitchen_prep::Reply { cases: &[(&["icing sugar", "powdered sugar", "icing"], "Yes: icing sugar clumps as soon as the bag is open, and a lump shows in icing or sits in a dusting like grit. A sieve is quicker than a whisk for a smooth glacé icing, and a fine one gives the even dusting you want on a cake."), (&["cocoa"], "Yes, always: cocoa is the one that clumps hardest, and lumps will not beat out of a batter or a sauce. Sift it with the flour or whisk it into hot water first.")], default: "Not from a fresh bag: modern plain and self-raising flour are already fine and loose. Sift it if the bag has been open for months, if there are lumps, or if you are making a light sponge or folding flour into beaten egg whites - the air sifting adds is what makes those rise. Cocoa powder always wants a sieve.", freezing: None }), shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/kitchen_prep.py:426
    RawRow { id: "prep-peel", domain: "kitchen_prep", reply: "", key: &[&["peel", "peels", "peeling", "peeled"],&["need", "needs", "needed", "have to", "has to", "should", "must", "necessary", "worth", "point", "bother", "bothering", "essential", "important"],], grouped: true, avoid: &["apple", "apples", "pear", "pears", "peach", "peaches", "plum", "plums", "banana", "bananas", "orange", "oranges", "kiwi", "avocado", "mango", "ginger", "garlic", "onion", "onions", "shallot", "shallots", "prawn", "prawns", "mushroom", "mushrooms"], ask: &[], slips: &[], bias: 3, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Prep(super::kitchen_prep::Gate::Needed), callback: Callback::Prep(super::kitchen_prep::Reply { cases: &[(&["mash", "mashed"], "Not for mash: scrub them and leave the skin on if you like the flecks - most of the fibre sits there - and peel after boiling if you want the mash white and smooth. Peeling raw potatoes takes a third of the flesh off with the skin, so if you peel first, boil them in their own water."), (&["roast", "roasting", "roastie", "roasties", "oven"], "Yes for roast potatoes: peel them, cut them the same size, parboil 8 minutes, drain, shake in the pan to rough up the edges, then roast at 200C (180C fan) in hot fat for 40 to 45 minutes. Skins left on make a good, quicker wedge - just not a crisp roastie."), (&["boil", "boiling", "boiled", "salad", "salad"], "Not unless you want them white: scrub new potatoes and boil them with the skins on - that is where the fibre and a good part of the flavour sit - and peel only for mash, for a smooth soup, or if the skin has gone green or damaged."), (&["butternut", "squash", "pumpkin"], "Only if you want it in cubes: roast the halves cut side down in their skins - the flesh scoops out clean - but peel it for a soup or a tray of cubes, and mind your hands, because the skin is hard and slippy."), (&["beetroot"], "Roast them whole in their skins and the skin slips off afterwards: foil at 200C (180C fan) for an hour, then rub it away with kitchen paper. Peel raw beetroot only if you are grating it raw - but wear gloves, because it stains."), (&["sweet potato", "sweet potatoes"], "No need: the skin of a sweet potato is thin, it crisps in the oven, and it is where much of the fibre sits - scrub it and roast or bake it whole. Peel it only for a mash or a smooth soup."), (&["cucumber", "cucumbers"], "Only if the skin is thick, waxy or bitter at the stem end: a supermarket cucumber is fine unpeeled, and scoring it with a fork lengthways gives the ridged look without losing anything."), (&["carrot", "carrots", "parsnip", "parsnips", "swede", "turnip"], "Only if they are old: a young carrot or parsnip wants a scrub with a brush, while an old one tastes soapy and woody with the skin on. Peel a thin layer rather than down to the core, because the sweetest part is just under it."), (&["tomato", "tomatoes"], "Only for a smooth sauce or a clear soup: cut a small cross in the base, drop them in boiling water for 30 seconds and then into cold, and the skins slip off. For a chunky sauce or a tray of roasted tomatoes leave them on - they soften and disappear anyway.")], default: "Only if the skin is thick, muddy or bitter. Scrubbing does the same job on anything thin-skinned and a good part of the flavour sits right under it, so peel as thinly as you can when you do.", freezing: None }), shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/kitchen_prep.py:426
    RawRow { id: "prep-prick", domain: "kitchen_prep", reply: "", key: &[&["prick", "pricks", "pricking", "pricked", "pierce", "piercing"],&["need", "needs", "needed", "have to", "has to", "should", "must", "necessary", "worth", "point", "bother", "bothering", "essential", "important"],], grouped: true, avoid: &["sausage", "sausages", "chipolata", "chipolatas", "black pudding"], ask: &[], slips: &[], bias: 1, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Prep(super::kitchen_prep::Gate::Needed), callback: Callback::Prep(super::kitchen_prep::Reply { cases: &[(&["potato", "potatoes", "jacket", "jackets", "spud", "spuds"], "Yes, 4 or 5 deep pricks with a fork: without them the steam has nowhere to go and a jacket potato bursts in the oven. Rub the skin with oil and salt first and it crisps while it bakes.")], default: "Yes for anything with a skin going into a hot oven or a microwave - a tomato, a potato, an aubergine - so the steam has somewhere to go instead of splitting it open.", freezing: None }), shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/kitchen_prep.py:426
    RawRow { id: "prep-score", domain: "kitchen_prep", reply: "", key: &[&["score", "scores", "scoring", "scored", "slash", "slashing", "slit", "slits", "slitting"],&["need", "needs", "needed", "have to", "has to", "should", "must", "necessary", "worth", "point", "bother", "bothering", "essential", "important", "how do i", "how to", "how should i", "how do you"],], grouped: true, avoid: &["bread", "dough", "loaf", "loaves", "sourdough", "banneton", "boules"], ask: &[], slips: &[], bias: 3, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Prep(super::kitchen_prep::Gate::HowOrWhether), callback: Callback::Prep(super::kitchen_prep::Reply { cases: &[(&["pork", "crackling", "belly", "shoulder"], "Yes for crackling: score the skin about a centimetre deep in a diamond pattern, dry it well, rub in plenty of salt and start the joint hot. The scores are what let the fat render out and the skin bubble."), (&["bread", "dough", "loaf", "sourdough"], "Yes: one slash about a centimetre deep just before it goes in the oven lets the loaf open where you chose rather than where it wants to. A wet blade and a quick, confident cut are what make it clean."), (&["sausage", "sausages", "chipolata", "chipolatas", "black pudding"], "Not scored, and usually not even pricked: a good butcher's sausage pricked loses its juice, so cook it gently instead - a moderate pan or a 180C oven - and it will not split. A cheap, tight-skinned one splits whatever you do to it."), (&["fish", "salmon", "cod", "bass", "trout", "skin"], "Yes for a crisp pan skin: three shallow slashes through the skin stop the fillet curling and let the heat through. Score it before it goes in the pan, and dry the skin well.")], default: "Yes when the skin has to let something out: a joint of pork for crackling, a loaf that has to open where you want it, a fish fillet that would curl. Score about a centimetre deep and dry the surface first.", freezing: None }), shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/kitchen_prep.py:426
    RawRow { id: "prep-rinse", domain: "kitchen_prep", reply: "", key: &[&["rinse", "rinses", "rinsing", "rinsed"],&["need", "needs", "needed", "have to", "has to", "should", "must", "necessary", "worth", "point", "bother", "bothering", "essential", "important"],], grouped: true, avoid: &["rice", "risotto", "sushi", "pudding", "mushroom", "mushrooms", "tinned", "canned", "already cooked", "drain", "chicken", "turkey", "beef", "pork", "lamb", "steak", "mince", "meat", "fish", "salmon", "prawn", "prawns", "bacon", "gammon", "sausage", "sausages"], ask: &[], slips: &[], bias: 1, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Prep(super::kitchen_prep::Gate::Needed), callback: Callback::Prep(super::kitchen_prep::Reply { cases: &[(&["quinoa"], "Yes, quinoa wants it: 30 seconds under cold water in a sieve takes off the saponin on the surface, which tastes soapy and bitter. It is the one grain that really needs it - and toast it dry in the pan afterwards and it smells nutty."), (&["barley", "pearl barley", "bulgur", "couscous", "lentil", "lentils"], "A quick rinse is enough, and it is mostly to check for grit and bits of husk: run cold water through it in a sieve until it runs clear. No soaking, no scrubbing - that is for dried beans, and it is a different question.")], default: "A quick rinse under cold water is enough for most grains and pulses - it clears out dust and loose husk, and takes no more than a few seconds in a sieve. Rice is the one where rinsing is a real choice: rinse for separate grains, leave it for a risotto or a rice pudding.", freezing: None }), shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/kitchen_prep.py:426
    RawRow { id: "prep-blanch", domain: "kitchen_prep", reply: "", key: &[&["blanch", "blanches", "blanching", "blanched", "refresh", "refreshing", "freeze", "freezes", "freezing", "frozen", "freezer"],&["need", "needs", "needed", "have to", "has to", "should", "must", "necessary", "worth", "point", "bother", "bothering", "essential", "important"],], grouped: true, avoid: &[], ask: &[], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Prep(super::kitchen_prep::Gate::Freezing), callback: Callback::Prep(super::kitchen_prep::Reply { cases: &[(&["almond", "almonds", "nut", "nuts", "hazelnut", "hazelnuts", "walnut", "walnuts", "pistachio", "pistachios"], "Only if you want the skins off: a minute in boiling water and then straight into cold, and each one slips out of its skin between your fingers. For flaked or ground almonds there is nothing to do."), (&["potato", "potatoes", "chips", "chip", "fries"], "For chips, yes: three minutes in boiling water, then drain and dry them completely before frying. That softens the outside, and the roughened surface is what turns crisp."), (&["tomato", "tomatoes"], "That is the peeling step: 30 seconds in boiling water and straight into cold, and the skins slip off. Nothing else needs it.")], default: "Only if you are eating them later: two minutes in boiling salted water and then straight into iced water keeps green vegetables bright and just-cooked for a salad or a reheat. Into the freezer, it is the step that matters most - a minute or two blanched, then dried and bagged, and it keeps a year instead of going limp and grassy. Eaten straight away, steam them instead - one pan, and they keep more of the vitamins.", freezing: Some("Yes before freezing: two minutes in boiling water, then straight into iced water, dry them and bag them. That is what stops the enzymes that turn them grey and soft, so they keep about a year instead of going limp and grassy in a couple of months, and they go into the pan straight from frozen. Cooked leftover vegetables are fine to freeze without blanching.") }), shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/kitchen_prep.py:426
    RawRow { id: "prep-parboil", domain: "kitchen_prep", reply: "", key: &[&["parboil", "parboils", "parboiling", "parboiled", "part boil", "partly boil"],&["need", "needs", "needed", "have to", "has to", "should", "must", "necessary", "worth", "point", "bother", "bothering", "essential", "important"],], grouped: true, avoid: &[], ask: &[], slips: &[], bias: 1, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Prep(super::kitchen_prep::Gate::Needed), callback: Callback::Prep(super::kitchen_prep::Reply { cases: &[], default: "Yes for roast potatoes and chips: about 8 minutes in boiling salted water until a knife goes in and the outside gives, then drain and shake them in the pan to roughen the edges, and roast at 200C (180C fan) in hot fat for 40 to 45 minutes. The roughened edges are what go crisp. Potatoes for mashing need the full boil, not this.", freezing: None }), shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/kitchen_prep.py:426
    RawRow { id: "prep-pat-dry", domain: "kitchen_prep", reply: "", key: &[&["pat", "pats", "patting", "patted", "dab", "dabs", "dabbing"],&["need", "needs", "needed", "have to", "has to", "should", "must", "necessary", "worth", "point", "bother", "bothering", "essential", "important"],], grouped: true, avoid: &[], ask: &[], slips: &[], bias: 2, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Prep(super::kitchen_prep::Gate::PatDry), callback: Callback::Prep(super::kitchen_prep::Reply { cases: &[], default: "Yes, and it is the step people skip: a wet surface steams instead of browning, so pat meat, fish and potatoes dry with kitchen paper and salt them just before they go in the pan. It matters most for a steak, a chicken breast with the skin on and anything going into a hot oven.", freezing: None }), shape: &[], lead: super::leading::Lead::None },
    // bot/knowledge/kitchen_prep.py:426
    RawRow { id: "prep-trim", domain: "kitchen_prep", reply: "", key: &[&["trim", "trims", "trimming", "trimmed", "top and tail", "top and tailing"],&["need", "needs", "needed", "have to", "has to", "should", "must", "necessary", "worth", "point", "bother", "bothering", "essential", "important"],], grouped: true, avoid: &[], ask: &[], slips: &[], bias: 1, explain: false, report: false, fault: false, outcomes: &[], guard: guards::Guard::Prep(super::kitchen_prep::Gate::Needed), callback: Callback::Prep(super::kitchen_prep::Reply { cases: &[(&["steak", "beef", "pork", "lamb", "chicken", "meat", "joint", "gammon"], "Only if you want it leaner: a rim of fat bastes the meat and is what you are paying for, so leave it on and cut it away on the plate. Silverskin - the shiny, tough membrane - is the one that must come off, or the meat curls."), (&["asparagus"], "Yes, and the woody end knows where it is: bend each spear until it snaps, and throw the stub away - it is fibrous and never softens. Do not cut them all at the same length by eye, or you will keep the tough part on the thin spears."), (&["leek", "leeks"], "Yes: cut off the dark green top for stock, and slit the leek lengthways down the white so the grit between the layers can rinse out. A leek that looks clean is usually the one with sand in it."), (&["celery"], "A rinse and a trim of the base is enough. If the strings bother you, peel them off the outside of the stalk with a vegetable peeler - the flavour is in the stalk, not the strings.")], default: "Only the tough bits: the stalk end of a bean, the woody end of an asparagus spear, the base of a sprout, the stringy root of a spring onion. Trimming more than that wastes the vegetable, and most of what people cut away cooks down to nothing anyway.", freezing: None }), shape: &[], lead: super::leading::Lead::None },
];
